 static readonly BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;static T Field<T>(MainForm form,string name){return (T)typeof(MainForm).GetField(name,Private).GetValue(form);}static object Call(MainForm form,string name,params object[] args){return typeof(MainForm).GetMethod(name,Private).Invoke(form,args);}static void Check(bool ok,string text){if(!ok)throw new Exception(text);}static IEnumerable<Control> All(Control root){foreach(Control child in root.Controls){yield return child;foreach(var next in All(child))yield return next;}}static void Save(Control control,string name){using(var image=new Bitmap(control.Width,control.Height)){control.DrawToBitmap(image,new Rectangle(Point.Empty,control.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name+".png"));}}
