 foreach(bool isSource in new[]{true,false}){if(!isSource){Call(form,"CommitTranslationResult","مرحبا بالعالم\r\n"+text,originalSource.Text,"ar","Arabic");translation.RightToLeft=RightToLeft.Yes;}var original=isSource?originalSource:translation;var expand=isSource?sourceExpand:resultExpand;string expected=original.Text,title=isSource?"Source":"Translation";int selection=original.SelectionStart;float fontSize=original.Font.Size;bool checkedDialog=false;
 using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text==title+" — ScreenText");if(dialog==null)return;timer.Stop();var reader=All(dialog).OfType<TextBox>().First(t=>t.AccessibleName=="Expanded "+title.ToLowerInvariant()+" text");Check(reader.Text==expected&&!reader.ReadOnly&&reader.WordWrap,"Expanded editor lost text or remains read-only");Check(reader.Font.Size==original.Font.Size,"Expanded default font differs from workspace");Check(reader.RightToLeft==original.RightToLeft,"Reader lost RTL direction");Check(dialog.MaximizeBox&&dialog.FormBorderStyle==FormBorderStyle.Sizable,"Reader cannot resize/maximize");var larger=All(dialog).OfType<Button>().First(b=>b.AccessibleName=="Increase reading text size");var smaller=All(dialog).OfType<Button>().First(b=>b.AccessibleName=="Decrease reading text size");larger.PerformClick();Check(reader.Font.Size==fontSize+1&&original.Font.Size==fontSize,"Reader zoom affected workspace");smaller.PerformClick();Check(reader.Font.Size==fontSize,"Reader zoom out failed");Check(original.SelectionStart==selection,"Zoom changed workspace selection");Check(reader.MaxLength==original.MaxLength,"Expanded editor limit differs");reader.AppendText("\r\nEdited in expanded "+title);expected=reader.Text;Check(original.Text==expected,"Expanded edits did not synchronize to workspace");All(dialog).OfType<Button>().First(b=>b.Text=="Copy text").PerformClick();Check(Clipboard.GetText()==expected,"Reader copy lost full text");Save(dialog,"Reading-"+title+"-"+mode);dialog.ClientSize=new Size(640,440);Application.DoEvents();foreach(var button in All(dialog).OfType<Button>())Check(button.Right<=button.Parent.ClientSize.Width&&button.Bottom<=button.Parent.ClientSize.Height,"Reader action clipped at minimum size");Check(reader.Width>300&&reader.Height>150,"Reader has insufficient text area");checkedDialog=true;All(dialog).OfType<Button>().First(b=>b.Text=="Done").PerformClick();};timer.Start();expand.PerformClick();}Check(checkedDialog&&original.Text==expected,"Reading changed workspace text/selection");}
 }
 bool synced=false;using(var timer=new System.Windows.Forms.Timer{Interval=100}){timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text=="Source — ScreenText");if(dialog==null)return;timer.Stop();originalSource.Text="Updated source while reader is open";var reader=All(dialog).OfType<TextBox>().First();Check(reader.Text==originalSource.Text,"Reader did not track updated source");synced=true;dialog.Close();};timer.Start();sourceExpand.PerformClick();}Check(synced,"Live reader sync was not exercised");originalSource.Text="After reading closes";originalSource.Clear();translation.Clear();Check(!sourceExpand.Enabled&&!resultExpand.Enabled,"Expand stayed enabled after clear");form.Size=form.MinimumSize;Application.DoEvents();Save(form,"Reading-main-minimum");Call(form,"ExitApplication");}
